   878  lexer_force_match(struct lexer *lexer, enum lex_type t)
   879  {
   880      if (t == LEX_T_END) {
   881          return lexer_force_end(lexer);
   882      } else if (lexer_match(lexer, t)) {
   883          return true;
   884      } else {
   885          struct lex_token token = { .type = t };
   886          struct ds s = DS_EMPTY_INITIALIZER;
   887          lex_token_format(&token, &s);
   888
   889          lexer_syntax_error(lexer, "expecting `%s'", ds_cstr(&s));
   890
   891          ds_destroy(&s);
   892
   893          return false;
   894      }
